using Commerce;

namespace Commerce.Tests;

[TestClass]
public sealed class ShoppingCartTests
{
    private ShoppingCart _cart;

    public ShoppingCartTests()
    {
        _cart = new ShoppingCart();
    }

    [TestMethod]
    public void GetTotal_EmptyCart_ReturnsZero()
    {
        Assert.AreEqual(0m, _cart.GetTotal());
    }

    [TestMethod]
    public void AddItem_SingleItem_IncreasesTotal()
    {
        _cart.AddItem("SKU-001", 9.99m, 1);

        Assert.AreEqual(9.99m, _cart.GetTotal());
    }

    [TestMethod]
    public void AddItem_MultipleQuantity_MultipliesPrice()
    {
        _cart.AddItem("SKU-001", 5.00m, 3);

        Assert.AreEqual(15.00m, _cart.GetTotal());
    }

    [TestMethod]
    public void AddItem_MultipleItems_SumsAll()
    {
        _cart.AddItem("SKU-001", 10.00m, 1);
        _cart.AddItem("SKU-002", 20.00m, 2);

        Assert.AreEqual(50.00m, _cart.GetTotal());
    }

    [TestMethod]
    public void RemoveItem_ExistingSku_ReturnsTrue()
    {
        _cart.AddItem("SKU-001", 10.00m, 1);

        Assert.IsTrue(_cart.RemoveItem("SKU-001"));
    }

    [TestMethod]
    public void RemoveItem_ExistingSku_RemovesFromTotal()
    {
        _cart.AddItem("SKU-001", 10.00m, 1);
        _cart.AddItem("SKU-002", 5.00m, 2);

        _cart.RemoveItem("SKU-001");

        Assert.AreEqual(10.00m, _cart.GetTotal());
    }

    [TestMethod]
    public void RemoveItem_NonExistingSku_ReturnsFalse()
    {
        _cart.AddItem("SKU-001", 10.00m, 1);

        Assert.IsFalse(_cart.RemoveItem("SKU-999"));
    }

    [TestMethod]
    public void RemoveItem_NonExistingSku_DoesNotChangeTotal()
    {
        _cart.AddItem("SKU-001", 10.00m, 2);

        _cart.RemoveItem("SKU-999");

        Assert.AreEqual(20.00m, _cart.GetTotal());
    }

    [TestMethod]
    [DataRow("A", 1.00, 1, 1.00)]
    [DataRow("B", 2.50, 4, 10.00)]
    [DataRow("C", 0.99, 10, 9.90)]
    public void AddItem_VariousInputs_CalculatesCorrectTotal(
        string sku, double price, int qty, double expectedTotal)
    {
        _cart.AddItem(sku, (decimal)price, qty);

        Assert.AreEqual((decimal)expectedTotal, _cart.GetTotal());
    }

    [TestMethod]
    public void RemoveItem_DuplicateSkus_RemovesAll()
    {
        _cart.AddItem("SKU-001", 10.00m, 1);
        _cart.AddItem("SKU-001", 15.00m, 2);

        _cart.RemoveItem("SKU-001");

        Assert.AreEqual(0m, _cart.GetTotal());
    }
}

